CREATE TABLE equipment_dictionary (
    version text PRIMARY KEY,
    locale text NOT NULL,
    description text NOT NULL,
    rules jsonb NOT NULL CHECK (jsonb_typeof(rules) = 'object')
);

CREATE TABLE equipment_travel_types (
    code text PRIMARY KEY,
    label text NOT NULL,
    position smallint NOT NULL UNIQUE CHECK (position > 0)
);

CREATE TABLE equipment_categories (
    code text PRIMARY KEY,
    label text NOT NULL,
    group_label text NOT NULL,
    position smallint NOT NULL UNIQUE CHECK (position > 0)
);

CREATE TABLE equipment_catalog (
    id uuid PRIMARY KEY,
    code text NOT NULL UNIQUE,
    label text COLLATE pg_catalog."unicode" NOT NULL CHECK (label = btrim(label) AND char_length(label) BETWEEN 1 AND 120),
    label_key text GENERATED ALWAYS AS (lower(label)) STORED,
    category text NOT NULL REFERENCES equipment_categories(code),
    travel_types text[] NOT NULL CHECK (cardinality(travel_types) > 0),
    carry_scope text NOT NULL CHECK (carry_scope IN ('personal', 'group')),
    condition text,
    unit text NOT NULL,
    is_active boolean NOT NULL,
    position smallint NOT NULL UNIQUE CHECK (position > 0)
);

CREATE INDEX equipment_catalog_label_idx ON equipment_catalog (label_key, position) WHERE is_active;

CREATE TABLE personal_equipment (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    owner_user_id uuid NOT NULL,
    label text COLLATE pg_catalog."unicode" NOT NULL CHECK (label = btrim(label) AND char_length(label) BETWEEN 1 AND 120),
    label_key text GENERATED ALWAYS AS (lower(label)) STORED,
    UNIQUE (owner_user_id, label_key)
);

CREATE TABLE equipment_commands (
    owner_user_id uuid NOT NULL,
    idempotency_key uuid NOT NULL,
    request_label text NOT NULL,
    response jsonb NOT NULL CHECK (jsonb_typeof(response) = 'object'),
    PRIMARY KEY (owner_user_id, idempotency_key)
);





REVOKE INSERT, UPDATE, DELETE ON equipment_dictionary, equipment_travel_types, equipment_categories, equipment_catalog FROM tropio_travel_runtime;
REVOKE UPDATE, DELETE ON personal_equipment, equipment_commands FROM tropio_travel_runtime;
